        _amount = clampLte(_amount, address(ETH_LIQUIDITY).balance);

        vm.prank(_caller);
        try ETH_LIQUIDITY.mint(_amount) {
            console.log("Caller true: ", _caller);
            assert(_caller == address(SUPER_WETH));
